def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

N_values = [7, 8]
results = {}

for N in N_values:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = {
        "S": S_N,
        "T": T_N
    }

print("--- Results ---")
for N, res in results.items():
    print(f"N={N}:")
    print(f"  S = {res['S']}")
    print(f"  T(N) = {res['T']}")
    print(f"  Match = {res['S'] == res['T']}")

def calculate_R_M(M):
    R_M = 0
    for a in range(1, M):
        for b in range(1, M):
            R_M += (a * b) % M
    return R_M

def required_R_M(M):
    # Required R_M = ((M-2) * M**2) / 2
    return ((M - 2) * M**2) / 2

M_values = [8, 9, 10]
results = {}

for M in M_values:
    R_M = calculate_R_M(M)
    Req_R_M = required_R_M(M)
    results[M] = {
        "R_M": R_M,
        "Required_R_M": Req_R_M
    }

for M, res in results.items():
    print(f"M={M} (N={M-1}):")
    print(f"  Actual R_M: {res['R_M']}")
    print(f"  Required R_M: {res['Required_R_M']}")
    print(f"  Match? {res['R_M'] == res['Required_R_M']}")

